prompt:
请只写一个文件 mc_gate_full.cpp（C++20，全局 main）。

【硬性约束】
1. 允许 include：
     "mc_gate_seed.h" "mc_gate_dgp.h" "mc_gate_panel.h" "mc_gate_baselines.h"
     "mc_gate_adapter.h" "mc_gate_output.h" "mc_gate_replay.h" "mc_gate_grid_cells.inc"
   标准头：<cstdint> <cstddef> <cstdio> <cstring> <string> <vector> <span> <cstdlib>
2. **不要**自己写 grid 表。`mc_gate_grid_cells.inc` **自带** `struct GridCell` 定义与 include guard：
   只要写一行 `#include "mc_gate_grid_cells.inc"`（放在哪个 include 之后都行），
   之后就能直接用 `kGridCells` 与 `sizeof(kGridCells)/sizeof(kGridCells[0])`（269 个元素）。
   取用时要转型：
      Family fam = static_cast<Family>(c.family);        // 0=gauss 1=t5 2=garch 3=shortvol
      Composition cmp = static_cast<Composition>(c.comp); // 0=null 1=one_good 2=mixed 3=mixed_signed 4=all_negative
   **不要再自己定义 GridCell**（会与 .inc 里的冲突）。
3. 不要重新定义任何已存在的函数。main 第一行 `using namespace mc_gate;`。
4. 构建带 -Werror，零警告。只打印规定的行。

【main 的步骤】

第 1 步 解析两个可选参数（顺序任意，缺省值如下）：
  --limit N      只跑前 N 个 cell（默认 269）
  --reps-cap M   每个 cell 的 reps 取 min(reps, M)（默认 0 表示不截断）
  用 std::strcmp/atoi 解析 argv。

第 2 步 记 total = cell 总数（269），limit = min(N, total)。打印：
  GRID total=<total> limit=<limit>
  （用 %d）

第 3 步 打开两个输出：
  FILE* fa = std::fopen("/tmp/qgate/C27/aggregates.jsonl", "wb");
  std::vector<OutputRecord> outs;   // 交给 write_decisions_jsonl_gz
  对 k = 0 .. limit-1：
    const GridCell& c = kGridCells[k];
    int reps = (cap > 0 && c.reps > cap) ? cap : c.reps;
    int sel[6] = {0,0,0,0,0,0};
    std::uint64_t fp = 0;
    对 rep = 0 .. reps-1：
      Family fam = static_cast<Family>(c.family);
      Composition cmp = static_cast<Composition>(c.comp);
      std::string key = dataset_key(comp_name(cmp), c.S, c.N, c.T, c.rho, c.dist, c.p, c.ds);
        // comp_name 必须自己写（仓库里没有这个函数），照抄：
        //   static const char* comp_name(Composition cc) {
        //       switch (cc) {
        //           case Composition::Null:        return "null";
        //           case Composition::OneGood:     return "one_good";
        //           case Composition::Mixed:       return "mixed";
        //           case Composition::MixedSigned: return "mixed_signed";
        //           case Composition::AllNegative: return "all_negative";
        //       }
        //       return "null";
        //   }
        // 写在 namespace 外、main 之前（用 static 避免 -Wmissing-declarations）
      ReturnMatrix m = generate_panel(fam, cmp, c.T, c.N, c.rho, c.S, key, rep, 0, 20261027ULL);
      fp 一律填 0（指纹不在本卡的白名单内，**不要调用 fnv1a64_bytes**）
      std::vector<double> flat((std::size_t)c.T*c.N);
      for i<c.T, t<c.N: flat[(size_t)i*c.N+t] = m.at(i,t);
      ResearchWindow w{ std::span<const double>(flat.data(), flat.size()),
                        (std::size_t)c.T, (std::size_t)c.N, fp };
      WindowStats st = make_window_stats(w, false);
      // 6 条规则；GATE 用 Decision，B0..B4 用 RuleResult（不同类型）
      Decision d = decide_from_stats(st, RuleConfig{ GateMode::Full, 0.05, 0.05 });
      RuleResult r1=rule_b0(m), r2=rule_b1(m,0.05), r3=rule_b2(m), r4=rule_b3(m), r5=rule_b4_cscv(m,6,0.5);
      if(d.selected) sel[0]++;
      if(r1.selected) sel[1]++; if(r2.selected) sel[2]++; if(r3.selected) sel[3]++;
      if(r4.selected) sel[4]++; if(r5.selected) sel[5]++;
      // 记录：**照抄这段**（两种结果的 index 类型不同，不要塞进同一个数组，本卡实测踩过）
      auto push1 = [&](const char* id, bool sel, long long idx, bool ab, std::string rsn) {
          OutputRecord o{};
          o.cell_id = c.cell_id; o.rep_id = rep; o.rule_id = id;
          o.selected = sel; o.index = idx; o.abstain = ab;
          o.returns_sha256 = fp; o.reason = std::move(rsn);
          outs.push_back(o);
      };
      push1("GATE_Full", d.selected, (long long)d.index, d.abstain,
            d.reason ? std::string(d.reason) : std::string("selected"));
      push1("B0", r1.selected, (long long)r1.index, false, "baseline");
      push1("B1", r2.selected, (long long)r2.index, false, "baseline");
      push1("B2", r3.selected, (long long)r3.index, false, "baseline");
      push1("B3", r4.selected, (long long)r4.index, false, "baseline");
      push1("B4", r5.selected, (long long)r5.index, false, "baseline");
    对 i=0..5 往 fa 写一行 JSON（**单行、无空格**）：
      {"cell_id":%d,"rule":"%s","reps":%d,"selected":%d}\n
    打印：CELL <cell_id> <reps> <reps*6>
  std::fclose(fa);

第 4 步 write_decisions_jsonl_gz("/tmp/qgate/C27/decisions.jsonl.gz", outs)；打印：
  AGG_CELLS <limit*6>        （用 %d）
  RECORDS <outs.size()>      （用 %zu 或强转 long long）

第 5 步 打印 GRID_DONE，return 0。

【输出纪律】
  GRID 1 行 + CELL × limit 行 + AGG_CELLS 1 行 + RECORDS 1 行 + GRID_DONE 1 行。
  全部 printf 到 stdout，不写 stderr。
